<template>
  <div class="github-status">
    <a
      class="github-status__desktop"
      :href="profileUrl"
      target="_blank"
      rel="noopener noreferrer"
      :aria-label="`GitHub status: ${statusEmoji} ${statusMessage}. View on GitHub.`"
    >
      <span
        class="github-status__emoji"
        :class="emojiAnimationClass"
        aria-hidden="true"
      >{{ statusEmoji || '…' }}</span>
      <span class="github-status__text">
        <span class="github-status__label">Current status</span>
        <span class="github-status__message">{{ statusMessage }}</span>
      </span>
    </a>

    <button
      class="github-status__toggle"
      type="button"
      :aria-expanded="String(isExpanded)"
      aria-controls="github-status-details"
      :aria-label="isExpanded ? 'Hide GitHub status' : 'Show GitHub status'"
      @click="isExpanded = !isExpanded"
    >
      <span
        class="github-status__emoji"
        :class="emojiAnimationClass"
        aria-hidden="true"
      >{{ statusEmoji || '…' }}</span>
    </button>

    <div v-show="isExpanded" id="github-status-details" class="github-status__details">
      <span class="github-status__label">Current status</span>
      <span class="github-status__message">{{ statusMessage }}</span>
      <a :href="profileUrl" target="_blank" rel="noopener noreferrer">View on GitHub</a>
    </div>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import home from '@/data/home.json';

const profileUrl = home.github.url;
const username = home.profile.username;
const statusFeedUrl = '/github-status.json';
const statusEmoji = ref('');
const statusMessage = ref('Loading status…');
const isExpanded = ref(false);
const emojiAnimationClass = computed(() => {
  if (['🤔', '🧐', '🤨'].includes(statusEmoji.value)) return 'github-status__emoji--thinking';
  if (['❤️', '❤', '💓', '💗', '💖', '💕', '💘'].includes(statusEmoji.value)) {
    return 'github-status__emoji--heartbeat';
  }
  if (statusEmoji.value === '🔥') return 'github-status__emoji--fire';
  if (['🎉', '🎊'].includes(statusEmoji.value)) return 'github-status__emoji--celebration';
  if (statusEmoji.value === '👋') return 'github-status__emoji--wave';
  if (['😴', '💤'].includes(statusEmoji.value)) return 'github-status__emoji--sleep';
  return '';
});
const refreshIntervalMs = 5 * 60 * 1000;
let refreshIntervalId;
let isFetchingStatus = false;
let hasLoadedStatus = false;

async function fetchGitHubStatus() {
  if (isFetchingStatus) return;
  isFetchingStatus = true;

  const controller = new AbortController();
  const timeoutId = window.setTimeout(() => controller.abort(), 15000);

  try {
    const response = await fetch(`${statusFeedUrl}?t=${Date.now()}`, {
      headers: {
        Accept: 'application/json',
      },
      cache: 'no-store',
      signal: controller.signal,
    });

    if (!response.ok) {
      throw new Error(`GitHub status feed request failed with status ${response.status}`);
    }

    const status = await response.json();
    if (
      status.username !== username
      || (status.emoji !== null && typeof status.emoji !== 'string')
      || (status.message !== null && typeof status.message !== 'string')
      || (status.updatedAt !== null && typeof status.updatedAt !== 'string')
    ) {
      throw new Error('GitHub status feed has an invalid format');
    }

    statusEmoji.value = status.emoji || '';
    statusMessage.value = status.updatedAt
      ? status.message || 'No status set'
      : 'Syncing status…';
    hasLoadedStatus = true;
  } catch (error) {
    console.warn('Unable to load the current GitHub profile status feed.', error);
    if (!hasLoadedStatus) statusMessage.value = 'Status temporarily unavailable';
  } finally {
    window.clearTimeout(timeoutId);
    isFetchingStatus = false;
  }
}

function refreshWhenVisible() {
  if (document.visibilityState === 'visible') fetchGitHubStatus();
}

onMounted(() => {
  fetchGitHubStatus();
  refreshIntervalId = window.setInterval(fetchGitHubStatus, refreshIntervalMs);
  document.addEventListener('visibilitychange', refreshWhenVisible);
});

onBeforeUnmount(() => {
  window.clearInterval(refreshIntervalId);
  document.removeEventListener('visibilitychange', refreshWhenVisible);
});
</script>
